    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # The bottom row's 5s mark vertical rails. Each column's source colors
    # encountered from top to bottom occupy the intervals between sources;
    # uppermost source colors fill upward to the top, preserving source cells.
    for c in range(w):
