            continue
        sources=[(r,g[r][c]) for r in range(h-1) if g[r][c]!=0]
        # source events set the color for the interval above each event,
        # until the preceding event; the lowest source extends down to base.
        for i,(r,color) in enumerate(sources):
            upper=sources[i-1][0]+1 if i>0 else 0
            for rr in range(upper,r):
                g[rr][c]=color
        # Cells below the lowest source down to the base inherit its color.
        if sources:
            for rr in range(sources[-1][0]+1,h-1):
                g[rr][c]=sources[-1][1]
    return g
